use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

/// Percent-encode a string for use as a URL query value.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

/// Convert days since 1970-01-01 to (year, month, day).
/// Howard Hinnant's `civil_from_days` algorithm, using i64 throughout.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = z.div_euclid(146097);
    let doe = z - era * 146097; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = doy - (153 * mp + 2) / 5 + 1; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 }; // [1, 12]
    let y = if m <= 2 { y + 1 } else { y };
    (y, m as u32, d as u32)
}

/// Format Unix seconds as "YYYY-MM-DD" (always exactly 10 characters).
/// Years are clamped to 1970..=9999 so the four-digit field never overflows.
fn date_string(secs: u64) -> String {
    const MAX_DAYS: i64 = 2_932_896; // 9999-12-31
    let days = ((secs / 86_400) as i64).min(MAX_DAYS);
    let (y, m, d) = civil_from_days(days);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        let now = wall_clock::now();

        // Enrichment lookup. Its result is deliberately discarded so that the
        // node's output does not depend on it.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&tick.reason)
        );
        let _ = http_client::fetch(&url);

        RunInfo {
            date: date_string(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
```

